def format_counts(email: int, chat: int, pager: int) -> str:
    return f"email={email},chat={chat},pager={pager}"

from formatting import format_counts
from routing import channel_for

count = int(input())
counts = {"email": 0, "chat": 0, "pager": 0}
for _ in range(count):
    team, severity, after_hours = input().split("|")
    channel = channel_for(severity, after_hours)
    counts[channel] += 1
    print(f"{team}:{channel}")
print(format_counts(counts["email"], counts["chat"], counts["pager"]))

def channel_for(severity: str, after_hours: str) -> str:
    if severity == "low":
        return "email"
    if severity == "high":
        return "pager" if after_hours == "yes" else "chat"
    return "pager"

source_texts.fsm_rollback_project:
def format_matcher(processed: int, terminated: bool, rejected: int) -> str:
    state = "yes" if terminated else "no"
    return f"processed={processed}|terminated={state}|rejected={rejected}"

from formatting import format_matcher
from matcher import can_accept, termination_after_rollback

count = int(input())
processed = 0
terminated = False
rejected = 0
for _ in range(count):
    action, token = input().split("|", 1)
    if action == "accept":
        if can_accept(terminated):
            processed += 1
            terminated = terminated or token == "stop"
            print("accept")
        else:
            rejected += 1
            print("reject")
    else:
        processed = max(processed - 1, 0)
        terminated = termination_after_rollback(terminated, token)
        print("rollback")
print(format_matcher(processed, terminated, rejected))

def can_accept(terminated: bool) -> bool:
    return not terminated

def termination_after_rollback(terminated: bool, removed_token: str) -> bool:
    if removed_token == "stop":
        return False
    return terminated

