pub fn format_config(visibility: &str, audit: &str, unknown: i64) -> String {
    format!("visibility={visibility}|audit={audit}|unknown={unknown}")
}

mod formatting;
mod policy;

use formatting::format_config;
use policy::{recover_audit, recover_visibility};
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let count: usize = lines.next().unwrap().parse().unwrap();
    let mut visibility = "tree";
    let mut audit = "off";
    let mut unknown = 0;
    for _ in 0..count {
        let mut parts = lines.next().unwrap().splitn(2, '|');
        let key = parts.next().unwrap();
        let setting = parts.next().unwrap();
        match key {
            "visibility" => visibility = setting,
            "audit" => audit = setting,
            _ => unknown += 1,
        }
    }
    println!("{}", format_config(
        recover_visibility(visibility, unknown),
        recover_audit(audit, unknown),
        unknown,
    ));
}

pub fn recover_visibility(visibility: &str, _unknown: i64) -> &str {
    visibility
}

pub fn recover_audit(audit: &str, _unknown: i64) -> &str {
    audit
}

source_texts.capacity_state_project:
pub fn can_accept(used: i64, units: i64, capacity: i64) -> bool {
    used + units <= capacity
}

pub fn format_capacity(used: i64, deferred: i64) -> String {
    format!("used={used},deferred={deferred}")
}

mod allocation;
mod formatting;

use allocation::can_accept;
use formatting::format_capacity;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let capacity: i64 = lines.next().unwrap().parse().unwrap();
    let count: usize = lines.next().unwrap().parse().unwrap();
    let (mut used, mut deferred) = (0, 0);
    for _ in 0..count {
        let mut parts = lines.next().unwrap().split('|');
        let id = parts.next().unwrap();
        let units: i64 = parts.next().unwrap().parse().unwrap();
        if can_accept(used, units, capacity) {
            println!("{id}:accept");
            used += units;
        } else {
            println!("{id}:defer");
            deferred += 1;
        }
    }
    println!("{}", format_capacity(used, deferred));
}

