    format!("entries={entries}|duplicates={duplicates}|uncached={uncached}")
}

pub fn entity_key(kind: &str, source_field: &str, _response_field: &str, value: &str) -> String {
    if source_field != "id" { return String::new(); }
    format!("{kind}:{value}")
}

mod formatting;
mod identity;

use formatting::format_cache_counts;
use identity::entity_key;
use std::collections::HashSet;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let count: usize = lines.next().unwrap().parse().unwrap();
    let mut seen = HashSet::new();
    let (mut duplicates, mut uncached) = (0, 0);
    for _ in 0..count {
        let mut parts = lines.next().unwrap().splitn(4, '|');
        let key = entity_key(
            parts.next().unwrap(), parts.next().unwrap(),
            parts.next().unwrap(), parts.next().unwrap(),
        );
        if key.is_empty() {
            uncached += 1;
            println!("uncached");
        } else if seen.contains(&key) {
            duplicates += 1;
            println!("duplicate={key}");
        } else {
            println!("stored={key}");
            seen.insert(key);
        }
    }
    println!("{}", format_cache_counts(seen.len(), duplicates, uncached));
}

